//! Chat: saved conversations with the open model.
//!
//! Every reply is generated by the model token by token and shown as it is written; nothing is
//! scripted. A chat is stored with its model in `models/<id>/chats/<chat>.json`, together with
//! its settings (context text, how much history is kept, reply length, sampling) and its
//! attachments. Text files are read by the model as part of the prompt; images are kept with the
//! chat for networks that can see them later (no current network reads images).
use super::*;
use yendory_engine::learn::corpus::normalize_ascii;
use yendory_engine::learn::sampling::{reply_with, Sampling};

/// Longest message in characters.
const MAX_MESSAGE_CHARS: usize = 8_000;
/// Longest context text in characters.
const MAX_CONTEXT_CHARS: usize = 20_000;
/// Largest text file (before conversion to the model's alphabet).
const MAX_TEXT_BYTES: usize = 2 << 20;
/// Largest image file.
const MAX_IMAGE_BYTES: usize = 8 << 20;
/// Attachments on one message.
const MAX_ATTACHMENTS: usize = 8;
const TEXT_TYPES: &[&str] = &[
    "txt", "md", "markdown", "csv", "tsv", "json", "jsonl", "log", "html", "htm", "xml", "yaml", "yml",
    "toml", "ini", "cfg", "rs", "py", "js", "ts", "c", "h", "cpp", "hpp", "cs", "java", "go", "sh", "bat",
    "ps1", "css", "sql", "tex",
];
const IMAGE_TYPES: &[(&str, &str)] = &[
    ("png", "image/png"),
    ("jpg", "image/jpeg"),
    ("jpeg", "image/jpeg"),
    ("gif", "image/gif"),
    ("webp", "image/webp"),
    ("bmp", "image/bmp"),
];

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub(crate) struct ChatSettings {
    /// Text put at the start of every prompt in this chat: background, instructions, facts.
    pub context: String,
    /// Earlier turns kept in the prompt: "all" (as many as fit), "last" (the last `turns` that
    /// fit) or "none" (every message on its own).
    pub history: String,
    pub turns: usize,
    /// Longest reply in tokens; 0 is Studio's default for the model's context.
    pub reply_tokens: usize,
    pub sampling: Sampling,
    /// Sampled replies use `sampling.seed` every time instead of a new seed per reply.
    pub fixed_seed: bool,
    /// Study Mode memories related to the message go in front of it (when Study Mode is on).
    pub memories: bool,
}
impl Default for ChatSettings {
    fn default() -> Self {
        ChatSettings {
            context: String::new(),
            history: "all".into(),
            turns: 6,
            reply_tokens: 0,
            sampling: Sampling::default(),
            fixed_seed: false,
            memories: true,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct Attachment {
    /// "text" or "image".
    pub kind: String,
    pub name: String,
    /// A text file as the model reads it (its alphabet: ASCII).
    #[serde(default)]
    pub text: String,
    /// An image as a data URL.
    #[serde(default)]
    pub data: String,
    /// Size of the file as attached.
    #[serde(default)]
    pub bytes: usize,
    /// Characters of a text file the model's alphabet cannot write (left out).
    #[serde(default)]
    pub dropped: usize,
    /// Tokens of a text file.
    #[serde(default)]
    pub tokens: usize,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct ReplyInfo {
    pub tokens: usize,
    pub millis: u64,
    /// Tokens of the prompt the reply was written after, and the model's context.
    pub prompt_tokens: usize,
    pub context: usize,
    pub reply_limit: usize,
    pub turns_used: usize,
    pub turns_left_out: usize,
    /// Tokens of attached text cut so the prompt fits.
    pub attachment_tokens_cut: usize,
    pub memories: Vec<String>,
    /// The reply ended on its own (rather than at the length limit or Stop).
    pub finished: bool,
    pub stopped: bool,
    /// The settings that chose its tokens, with the seed actually used.
    pub sampling: Sampling,
    /// The model's training step when it replied.
    pub step: u64,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct Message {
    /// "user" or "model".
    pub role: String,
    pub text: String,
    pub time: u64,
    #[serde(default)]
    pub attachments: Vec<Attachment>,
    /// Characters of the typed message the model's alphabet cannot write (left out).
    #[serde(default)]
    pub dropped: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub info: Option<ReplyInfo>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct Chat {
    pub id: String,
    pub title: String,
    pub created: u64,
    pub updated: u64,
    #[serde(default)]
    pub pinned: bool,
    #[serde(default)]
    pub settings: ChatSettings,
    #[serde(default)]
    pub messages: Vec<Message>,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct ChatSummary {
    id: String,
    title: String,
    updated: u64,
    pinned: bool,
    messages: usize,
    preview: String,
}

fn chats_dir(app: &AppHandle, model_id: &str) -> Res<PathBuf> {
    Ok(model_dir(app, model_id)?.join("chats"))
}

fn chat_path(app: &AppHandle, model_id: &str, id: &str) -> Res<PathBuf> {
    if id.is_empty() || id.len() > 40 || !id.chars().all(|c| c.is_ascii_alphanumeric()) {
        return Err("Invalid chat id".into());
    }
    Ok(chats_dir(app, model_id)?.join(format!("{id}.json")))
}

fn load_chat(app: &AppHandle, model_id: &str, id: &str) -> Res<Chat> {
    let path = chat_path(app, model_id, id)?;
    let bytes = std::fs::read(&path).map_err(|_| "This chat no longer exists".to_string())?;
    serde_json::from_slice(&bytes).map_err(|e| format!("This chat could not be read: {e}"))
}

fn save_chat(app: &AppHandle, model_id: &str, chat: &Chat) -> Res<()> {
    let path = chat_path(app, model_id, &chat.id)?;
    std::fs::create_dir_all(path.parent().unwrap()).map_err(|e| e.to_string())?;
    write_atomic(&path, &serde_json::to_vec(chat).map_err(|e| e.to_string())?)
}

fn active_id(studio: &Studio) -> Res<String> {
    with_active(studio, |a| Ok(a.meta.id.clone()))
}

fn new_chat_id() -> String {
    let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
    format!("c{nanos:x}")
}

fn snippet(text: &str, chars: usize) -> String {
    let one: String = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if one.chars().count() <= chars {
        return one;
    }
    let cut: String = one.chars().take(chars).collect();
    format!("{}…", cut.trim_end())
}

/// Text the model can read: its alphabet (ASCII), no control characters or Nexus markers.
/// Returns the text and the characters left out.
fn readable_text(text: &str) -> (String, usize) {
    let (ascii, dropped) = normalize_ascii(text);
    (yendory_engine::nexus::sanitize(&ascii), dropped)
}

fn check_settings(mut s: ChatSettings) -> Res<ChatSettings> {
    if s.context.chars().count() > MAX_CONTEXT_CHARS {
        return Err(format!("The context text is longer than {MAX_CONTEXT_CHARS} characters"));
    }
    s.context = readable_text(&s.context).0.trim().to_string();
    if !["all", "last", "none"].contains(&s.history.as_str()) {
        s.history = "all".into();
    }
    s.turns = s.turns.clamp(1, 1000);
    s.reply_tokens = s.reply_tokens.min(8192);
    s.sampling = s.sampling.clamped();
    s.sampling.top_k = s.sampling.top_k.min(1_000_000);
    Ok(s)
}

/// An attachment checked and in the form the model reads (text files are converted again, so a
/// chat file edited by hand cannot put anything else in a prompt).
fn check_attachment(model: &Bicameral, mut a: Attachment) -> Res<Attachment> {
    a.name = snippet(&yendory_engine::nexus::sanitize(&a.name), 120);
    match a.kind.as_str() {
        "text" => {
            if a.text.len() > MAX_TEXT_BYTES * 2 {
                return Err(format!("{} is too large", a.name));
            }
            let (text, dropped) = readable_text(&a.text);
            a.text = text;
            a.dropped = a.dropped.max(dropped);
            a.data.clear();
            a.tokens = model.tokenizer.encode(&a.text)?.len();
        }
        "image" => {
            let ok = IMAGE_TYPES.iter().any(|(_, mime)| a.data.starts_with(&format!("data:{mime};base64,")));
            if !ok {
                return Err(format!("{}: not a PNG, JPEG, GIF, WebP or BMP image", a.name));
            }
            if a.data.len() > MAX_IMAGE_BYTES * 4 / 3 + 64 {
                return Err(format!("{} is larger than {} MB", a.name, MAX_IMAGE_BYTES >> 20));
            }
            a.text.clear();
            a.tokens = 0;
        }
        _ => return Err("Only text files and images can be attached".into()),
    }
    Ok(a)
}

fn base64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for c in bytes.chunks(3) {
        let n = (c[0] as u32) << 16 | (*c.get(1).unwrap_or(&0) as u32) << 8 | *c.get(2).unwrap_or(&0) as u32;
        out.push(T[(n >> 18) as usize & 63] as char);
        out.push(T[(n >> 12) as usize & 63] as char);
        out.push(if c.len() > 1 { T[(n >> 6) as usize & 63] as char } else { '=' });
        out.push(if c.len() > 2 { T[n as usize & 63] as char } else { '=' });
    }
    out
}

/// An attachment from a file's name and bytes.
fn attachment_of(model: &Bicameral, name: &str, bytes: Vec<u8>) -> Res<Attachment> {
    let ext = name.rsplit('.').next().unwrap_or("").to_ascii_lowercase();
    if let Some((_, mime)) = IMAGE_TYPES.iter().find(|(e, _)| *e == ext) {
        if bytes.len() > MAX_IMAGE_BYTES {
            return Err(format!("{name} is larger than {} MB", MAX_IMAGE_BYTES >> 20));
        }
        let a = Attachment {
            kind: "image".into(),
            name: name.into(),
            text: String::new(),
            data: format!("data:{mime};base64,{}", base64(&bytes)),
            bytes: bytes.len(),
            dropped: 0,
            tokens: 0,
        };
        return check_attachment(model, a);
    }
    if !TEXT_TYPES.contains(&ext.as_str()) && !ext.is_empty() && name.contains('.') {
        return Err(format!("{name}: only text files and images can be attached"));
    }
    if bytes.len() > MAX_TEXT_BYTES {
        return Err(format!("{name} is larger than {} MB", MAX_TEXT_BYTES >> 20));
    }
    let text = String::from_utf8(bytes.clone()).map_err(|_| format!("{name}: not a text file"))?;
    let plain = if matches!(ext.as_str(), "md" | "markdown") {
        yendory_engine::learn::designer::markdown_to_plain(&normalize_ascii(&text).0)
    } else {
        text
    };
    let dropped = normalize_ascii(&plain).1;
    let a = Attachment {
        kind: "text".into(),
        name: name.into(),
        text: plain,
        data: String::new(),
        bytes: bytes.len(),
        dropped,
        tokens: 0,
    };
    check_attachment(model, a)
}

/// The prompt for a reply and how the context was spent.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub(crate) struct Budget {
    #[serde(skip)]
    prompt: String,
    prompt_tokens: usize,
    context: usize,
    reply_limit: usize,
    context_text_tokens: usize,
    memory_tokens: usize,
    history_tokens: usize,
    attachment_tokens: usize,
    message_tokens: usize,
    turns_used: usize,
    turns_left_out: usize,
    attachment_tokens_cut: usize,
}

/// Longest reply for a chat: its setting, else Studio's default for the context; always leaving
/// room for a prompt.
fn reply_limit(settings: &ChatSettings, context: usize) -> usize {
    let default = reply_length(context);
    let want = if settings.reply_tokens > 0 { settings.reply_tokens } else { default };
    want.clamp(1, (context / 2).max(1))
}

/// The text attachments of a message as prompt lines.
fn attached_text(attachments: &[Attachment]) -> String {
    let mut out = String::new();
    for a in attachments.iter().filter(|a| a.kind == "text") {
        let t = a.text.trim();
        if !t.is_empty() {
            out.push_str(t);
            out.push('\n');
        }
    }
    out
}

fn one_line(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// The prompt: the context text, Study Mode memories, earlier turns (newest kept first, each
/// with its attached text when it fits), this message's attached text (cut if it does not fit)
/// and the message. Turns are written as the model was taught them: `U: …` then `N: …`.
fn build_prompt(
    model: &Bicameral,
    settings: &ChatSettings,
    earlier: &[Message],
    message: &Message,
    memory: &str,
) -> Res<Budget> {
    let tok = |s: &str| -> Res<usize> { Ok(model.tokenizer.encode(s)?.len()) };
    let context = model.config.max_tokens;
    let reply = reply_limit(settings, context);
    let room = context - reply;
    let context_text =
        if settings.context.is_empty() { String::new() } else { format!("{}\n", settings.context) };
    let context_text_tokens = tok(&context_text)?;
    let question = format!("U: {}\nN: ", one_line(&message.text));
    let message_tokens = tok(&question)?;
    if context_text_tokens + message_tokens > room {
        return Err(format!(
            "The context text and the message take {} tokens; this model reads {context} tokens at once and {reply} are kept for the reply. Shorten them, the reply length, or change the model's context on § 1 Models.",
            context_text_tokens + message_tokens
        ));
    }
    let mut used = context_text_tokens + message_tokens;
    let memory_tokens = if memory.is_empty() { 0 } else { tok(memory)? };
    let memory = if used + memory_tokens <= room { memory } else { "" };
    let memory_tokens = if memory.is_empty() { 0 } else { memory_tokens };
    used += memory_tokens;
    // This message's attached text comes before the history: cut to what is left.
    let mut attached = attached_text(&message.attachments);
    let mut attachment_tokens = tok(&attached)?;
    let mut attachment_tokens_cut = 0;
    if used + attachment_tokens > room {
        // One token is kept for the line break after the cut text.
        let ids = model.tokenizer.encode(&attached)?;
        let keep = (room - used).saturating_sub(1);
        attachment_tokens_cut = ids.len() - keep;
        attached = model.tokenizer.decode(&ids[..keep])?;
        if !attached.is_empty() && !attached.ends_with('\n') {
            attached.push('\n');
        }
        attachment_tokens = tok(&attached)?;
    }
    used += attachment_tokens;
    // Earlier turns: a user message answered by the model.
    let mut pairs: Vec<(&Message, &Message)> = Vec::new();
    let mut i = 0;
    while i + 1 < earlier.len() {
        if earlier[i].role == "user" && earlier[i + 1].role == "model" {
            pairs.push((&earlier[i], &earlier[i + 1]));
            i += 2;
        } else {
            i += 1;
        }
    }
    let allowed = match settings.history.as_str() {
        "none" => 0,
        "last" => settings.turns,
        _ => usize::MAX,
    };
    let mut turns = Vec::new();
    let mut history_tokens = 0;
    for (user, said) in pairs.iter().rev() {
        if turns.len() >= allowed {
            break;
        }
        let line = format!(
            "U: {}\nN: {}\n",
            one_line(&user.text),
            one_line(&yendory_engine::nexus::sanitize(&said.text))
        );
        let with_files = format!("{}{line}", attached_text(&user.attachments));
        let (text, n) = match tok(&with_files)? {
            n if used + n <= room => (with_files, n),
            _ => match tok(&line)? {
                n if used + n <= room => (line, n),
                _ => break,
            },
        };
        used += n;
        history_tokens += n;
        turns.push(text);
    }
    // Pieces joined can tokenize differently from apart (rarely): the oldest turns kept go
    // until the whole fits.
    let assemble = |turns: &[String]| -> String {
        [context_text.as_str(), memory]
            .into_iter()
            .chain(turns.iter().rev().map(String::as_str))
            .chain([attached.as_str(), question.as_str()])
            .collect()
    };
    let mut prompt = assemble(&turns);
    let mut prompt_tokens = tok(&prompt)?;
    while prompt_tokens > room && !turns.is_empty() {
        let dropped = turns.pop().unwrap();
        history_tokens = history_tokens.saturating_sub(tok(&dropped)?);
        prompt = assemble(&turns);
        prompt_tokens = tok(&prompt)?;
    }
    let turns_used = turns.len();
    if prompt_tokens > room {
        // Never send more than fits.
        return Err(format!(
            "The prompt takes {prompt_tokens} tokens, more than the {room} available; shorten the message or the context text"
        ));
    }
    Ok(Budget {
        prompt,
        prompt_tokens,
        context,
        reply_limit: reply,
        context_text_tokens,
        memory_tokens,
        history_tokens,
        attachment_tokens,
        message_tokens,
        turns_used,
        turns_left_out: pairs.len() - turns_used,
        attachment_tokens_cut,
    })
}

fn user_message(model: &Bicameral, text: &str, attachments: Vec<Attachment>) -> Res<Message> {
    if text.chars().count() > MAX_MESSAGE_CHARS {
        return Err(format!("Write a message of at most {MAX_MESSAGE_CHARS} characters"));
    }
    if attachments.len() > MAX_ATTACHMENTS {
        return Err(format!("At most {MAX_ATTACHMENTS} files can be attached to a message"));
    }
    let (clean, dropped) = readable_text(text);
    let clean = clean.trim().to_string();
    if clean.is_empty() {
        return Err(if attachments.is_empty() || dropped > 0 {
            "Write a message (the model reads English letters, digits and punctuation)".into()
        } else {
            "Write a message to go with the attached files".into()
        });
    }
    let attachments = attachments.into_iter().map(|a| check_attachment(model, a)).collect::<Res<Vec<_>>>()?;
    Ok(Message { role: "user".into(), text: clean, time: now(), attachments, dropped, info: None })
}

// ---------------------------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------------------------

/// The open model's chats, pinned first, then the most recent.
#[tauri::command]
pub(crate) fn chats(app: AppHandle, studio: State<Studio>) -> Res<Vec<ChatSummary>> {
    let Ok(model_id) = active_id(&studio) else { return Ok(Vec::new()) };
    let dir = chats_dir(&app, &model_id)?;
    let mut out = Vec::new();
    for entry in std::fs::read_dir(&dir).into_iter().flatten().flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let Ok(chat) = std::fs::read(&path)
            .map_err(|e| e.to_string())
            .and_then(|b| serde_json::from_slice::<Chat>(&b).map_err(|e| e.to_string()))
        else {
            continue;
        };
        let preview = chat.messages.last().map(|m| snippet(&m.text, 80)).unwrap_or_default();
        out.push(ChatSummary {
            id: chat.id,
            title: chat.title,
            updated: chat.updated,
            pinned: chat.pinned,
            messages: chat.messages.len(),
            preview,
        });
    }
    out.sort_by(|a, b| b.pinned.cmp(&a.pinned).then(b.updated.cmp(&a.updated)).then(b.id.cmp(&a.id)));
    Ok(out)
}

#[tauri::command]
pub(crate) fn chat_open(app: AppHandle, studio: State<Studio>, id: String) -> Res<Chat> {
    load_chat(&app, &active_id(&studio)?, &id)
}

/// A new, empty chat with the given settings (a new chat usually keeps the settings of the one
/// open before it).
#[tauri::command]
pub(crate) fn chat_new(app: AppHandle, studio: State<Studio>, settings: Option<ChatSettings>) -> Res<Chat> {
    let model_id = active_id(&studio)?;
    let t = now();
    let chat = Chat {
        id: new_chat_id(),
        title: "New chat".into(),
        created: t,
        updated: t,
        pinned: false,
        settings: check_settings(settings.unwrap_or_default())?,
        messages: Vec::new(),
    };
    save_chat(&app, &model_id, &chat)?;
    Ok(chat)
}

#[tauri::command]
pub(crate) fn chat_rename(app: AppHandle, studio: State<Studio>, id: String, title: String) -> Res<Chat> {
    let model_id = active_id(&studio)?;
    let title = title.trim();
    if title.is_empty() || title.chars().count() > 80 || title.chars().any(char::is_control) {
        return Err("Give the chat a title of 1 to 80 characters".into());
    }
    let mut chat = load_chat(&app, &model_id, &id)?;
    chat.title = title.to_string();
    save_chat(&app, &model_id, &chat)?;
    Ok(chat)
}

#[tauri::command]
pub(crate) fn chat_pin(app: AppHandle, studio: State<Studio>, id: String, pinned: bool) -> Res<Chat> {
    let model_id = active_id(&studio)?;
    let mut chat = load_chat(&app, &model_id, &id)?;
    chat.pinned = pinned;
    save_chat(&app, &model_id, &chat)?;
    Ok(chat)
}

#[tauri::command]
pub(crate) fn chat_delete(app: AppHandle, studio: State<Studio>, id: String) -> Res<()> {
    let model_id = active_id(&studio)?;
    let path = chat_path(&app, &model_id, &id)?;
    if path.exists() {
        std::fs::remove_file(path).map_err(|e| e.to_string())?;
    }
    Ok(())
}

#[tauri::command]
pub(crate) fn chat_settings(
    app: AppHandle,
    studio: State<Studio>,
    id: String,
    settings: ChatSettings,
) -> Res<Chat> {
    let model_id = active_id(&studio)?;
    let mut chat = load_chat(&app, &model_id, &id)?;
    chat.settings = check_settings(settings)?;
    save_chat(&app, &model_id, &chat)?;
    Ok(chat)
}

/// Files chosen in the file dialog, as attachments.
#[tauri::command]
pub(crate) async fn chat_attach(app: AppHandle, studio: State<'_, Studio>) -> Res<Vec<Attachment>> {
    let model = with_active(&studio, |a| Ok(a.model.clone()))?;
    let types: Vec<&str> = TEXT_TYPES.iter().copied().chain(IMAGE_TYPES.iter().map(|(e, _)| *e)).collect();
    let Some(paths) = app
        .dialog()
        .file()
        .add_filter("Text files and images", &types)
        .add_filter("Images", &IMAGE_TYPES.iter().map(|(e, _)| *e).collect::<Vec<_>>())
        .add_filter("Text files", TEXT_TYPES)
        .blocking_pick_files()
    else {
        return Ok(Vec::new());
    };
    paths
        .iter()
        .take(MAX_ATTACHMENTS)
        .map(|p| {
            let name = display_name(p);
            attachment_of(&model, &name, read_picked(&app, p, MAX_IMAGE_BYTES.max(MAX_TEXT_BYTES))?)
        })
        .collect()
}

/// Files dropped on the window (desktop), as attachments.
#[tauri::command]
pub(crate) async fn chat_attach_paths(studio: State<'_, Studio>, paths: Vec<String>) -> Res<Vec<Attachment>> {
    let model = with_active(&studio, |a| Ok(a.model.clone()))?;
    paths
        .iter()
        .take(MAX_ATTACHMENTS)
        .map(|p| {
            let path = std::path::Path::new(p);
            let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("file").to_string();
            let size = std::fs::metadata(path).map_err(|e| format!("{name}: {e}"))?.len() as usize;
            if size > MAX_IMAGE_BYTES.max(MAX_TEXT_BYTES) {
                return Err(format!("{name} is too large"));
            }
            attachment_of(&model, &name, std::fs::read(path).map_err(|e| format!("{name}: {e}"))?)
        })
        .collect()
}

/// How the context would be spent on this message (Study Mode memories are found when the
/// message is sent, so they are not counted here).
#[tauri::command]
pub(crate) fn chat_measure(
    app: AppHandle,
    studio: State<Studio>,
    id: Option<String>,
    settings: ChatSettings,
    text: String,
    attachments: Vec<Attachment>,
    edit: Option<usize>,
) -> Res<Budget> {
    let (model_id, model) = with_active(&studio, |a| Ok((a.meta.id.clone(), a.model.clone())))?;
    let earlier = match id {
        Some(id) => {
            let mut messages = load_chat(&app, &model_id, &id)?.messages;
            messages.truncate(edit.unwrap_or(messages.len()));
            messages
        }
        None => Vec::new(),
    };
    let text = if text.trim().is_empty() { "?".to_string() } else { text };
    let message = user_message(&model, &text, attachments)?;
    build_prompt(&model, &check_settings(settings)?, &earlier, &message, "")
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct Token<'a> {
    chat: &'a str,
    text: &'a str,
}

/// Generates the model's reply to the chat's last message, streaming its text as "chat-token"
/// events, and saves it.
async fn respond(
    app: AppHandle,
    studio: &Studio,
    model_id: String,
    model: Bicameral,
    mut chat: Chat,
) -> Res<Chat> {
    let message = chat.messages.last().cloned().ok_or("Nothing to reply to")?;
    let earlier = chat.messages[..chat.messages.len() - 1].to_vec();
    let (memory, memories) = if chat.settings.memories {
        study::conversation_memories(&app, &model_id, &model, &one_line(&message.text))
    } else {
        (String::new(), Vec::new())
    };
    let budget = build_prompt(&model, &chat.settings, &earlier, &message, &memory)?;
    let mut sampling = chat.settings.sampling;
    if !chat.settings.fixed_seed {
        sampling.seed =
            SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(1);
    }
    studio.chat_stop.store(false, Ordering::Release);
    let stop = studio.chat_stop.clone();
    let id = chat.id.clone();
    let app2 = app.clone();
    let step = model.step;
    let started = std::time::Instant::now();
    let prompt = budget.prompt.clone();
    let limit = budget.reply_limit;
    let reply = tauri::async_runtime::spawn_blocking(move || {
        reply_with(&model, &prompt, limit, &sampling, |text| {
            // Shown readably: a marker the model writes appears as "Action:" and so on.
            let text = yendory_engine::nexus::readable(text);
            let _ = app2.emit("chat-token", Token { chat: &id, text: &text });
            !stop.load(Ordering::Acquire)
        })
    })
    .await
    .map_err(|e| e.to_string())??;
    chat.messages.push(Message {
        role: "model".into(),
        text: yendory_engine::nexus::readable(&reply.text),
        time: now(),
        attachments: Vec::new(),
        dropped: 0,
        info: Some(ReplyInfo {
            tokens: reply.tokens,
            millis: started.elapsed().as_millis() as u64,
            prompt_tokens: budget.prompt_tokens,
            context: budget.context,
            reply_limit: budget.reply_limit,
            turns_used: budget.turns_used,
            turns_left_out: budget.turns_left_out,
            attachment_tokens_cut: budget.attachment_tokens_cut,
            memories,
            finished: reply.finished,
            stopped: reply.stopped,
            sampling,
            step,
        }),
    });
    chat.updated = now();
    save_chat(&app, &model_id, &chat)?;
    Ok(chat)
}

/// Marks a reply as being written; one at a time.
struct Replying<'a>(&'a Studio);
impl<'a> Replying<'a> {
    fn start(studio: &'a Studio) -> Res<Self> {
        if studio.chatting.swap(true, Ordering::AcqRel) {
            return Err("The model is still writing a reply".into());
        }
        Ok(Replying(studio))
    }
}
impl Drop for Replying<'_> {
    fn drop(&mut self) {
        self.0.chatting.store(false, Ordering::Release);
    }
}

/// Sends a message and returns the chat with the model's reply. `edit` replaces the message at
/// that index (and everything after it) with this one.
#[tauri::command]
pub(crate) async fn chat_send(
    app: AppHandle,
    studio: State<'_, Studio>,
    id: String,
    text: String,
    attachments: Vec<Attachment>,
    edit: Option<usize>,
) -> Res<Chat> {
    let _replying = Replying::start(&studio)?;
    let (model_id, model) = with_active(&studio, |a| Ok((a.meta.id.clone(), a.model.clone())))?;
    let mut chat = load_chat(&app, &model_id, &id)?;
    let message = user_message(&model, &text, attachments)?;
    if let Some(i) = edit {
        if chat.messages.get(i).map(|m| m.role.as_str()) != Some("user") {
            return Err("Only your own messages can be edited".into());
        }
        chat.messages.truncate(i);
    }
    // Checked before anything is saved: a message that cannot fit is not added.
    build_prompt(&model, &chat.settings, &chat.messages, &message, "")?;
    if chat.title == "New chat" && !chat.messages.iter().any(|m| m.role == "user") {
        chat.title = snippet(&message.text, 48);
    }
    chat.messages.push(message);
    chat.updated = now();
    save_chat(&app, &model_id, &chat)?;
    respond(app, &studio, model_id, model, chat).await
}

/// Writes the model's reply to the last message again (the last reply, if any, is replaced).
#[tauri::command]
pub(crate) async fn chat_regenerate(app: AppHandle, studio: State<'_, Studio>, id: String) -> Res<Chat> {
    let _replying = Replying::start(&studio)?;
    let (model_id, model) = with_active(&studio, |a| Ok((a.meta.id.clone(), a.model.clone())))?;
    let mut chat = load_chat(&app, &model_id, &id)?;
    while chat.messages.last().is_some_and(|m| m.role == "model") {
        chat.messages.pop();
    }
    if chat.messages.is_empty() {
        return Err("There is no message to reply to".into());
    }
    respond(app, &studio, model_id, model, chat).await
}

/// Stops the reply being written (what was written so far is kept).
#[tauri::command]
pub(crate) fn chat_stop(studio: State<Studio>) -> bool {
    studio.chat_stop.store(true, Ordering::Release);
    studio.chatting.load(Ordering::Acquire)
}

/// Saves a chat as a text transcript.
#[tauri::command]
pub(crate) async fn chat_export(
    app: AppHandle,
    studio: State<'_, Studio>,
    id: String,
) -> Res<Option<String>> {
    let (model_id, model_name) = with_active(&studio, |a| Ok((a.meta.id.clone(), a.meta.name.clone())))?;
    let chat = load_chat(&app, &model_id, &id)?;
    let mut out = format!("# {}\n\nA chat with {model_name} in Yendory Studio.\n", chat.title);
    if !chat.settings.context.is_empty() {
        out.push_str(&format!("\nContext:\n{}\n", chat.settings.context));
    }
    for m in &chat.messages {
        let who = if m.role == "user" { "You" } else { model_name.as_str() };
        out.push_str(&format!("\n{who}:\n{}\n", m.text));
        for a in &m.attachments {
            out.push_str(&format!("[attached {}: {}]\n", a.kind, a.name));
        }
    }
    let safe: String = chat
        .title
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() || c == '-' { c } else { '_' })
        .take(48)
        .collect();
    let Some(path) = app
        .dialog()
        .file()
        .add_filter("Text", &["md", "txt"])
        .set_file_name(format!("{safe}.md"))
        .blocking_save_file()
    else {
        return Ok(None);
    };
    let mut opts = OpenOptions::new();
    opts.write(true).create(true).truncate(true);
    let mut file = app.fs().open(path.clone(), opts).map_err(|e| e.to_string())?;
    file.write_all(out.as_bytes()).map_err(|e| e.to_string())?;
    file.sync_all().map_err(|e| e.to_string())?;
    Ok(Some(display_name(&path)))
}

#[cfg(test)]
mod tests {
    use super::*;
    use yendory_engine::model::Config;

    fn model(context: usize) -> Bicameral {
        let cfg = Config {
            d: 16,
            heads: 2,
            ff: 24,
            blocks: 2,
            split: 1,
            r1: 12,
            r2: 10,
            max_tokens: context,
            ..Config::default()
        };
        Bicameral::with_config(cfg, 3)
    }
    fn msg(role: &str, text: &str) -> Message {
        Message {
            role: role.into(),
            text: text.into(),
            time: 0,
            attachments: Vec::new(),
            dropped: 0,
            info: None,
        }
    }

    #[test]
    fn prompt_keeps_context_history_and_message_in_order() {
        let m = model(256);
        let s = ChatSettings { context: "You are Nova.".into(), ..ChatSettings::default() };
        let earlier =
            [msg("user", "hi"), msg("model", "hello"), msg("user", "how are\nyou"), msg("model", "well")];
        let b = build_prompt(&m, &s, &earlier, &msg("user", "and now?"), "").unwrap();
        assert_eq!(b.prompt, "You are Nova.\nU: hi\nN: hello\nU: how are you\nN: well\nU: and now?\nN: ");
        assert_eq!(b.turns_used, 2);
        assert_eq!(b.prompt_tokens, m.tokenizer.encode(&b.prompt).unwrap().len());
        assert!(b.prompt_tokens + b.reply_limit <= 256);
        let none = ChatSettings { history: "none".into(), ..ChatSettings::default() };
        let b = build_prompt(&m, &none, &earlier, &msg("user", "x"), "").unwrap();
        assert_eq!((b.prompt.as_str(), b.turns_left_out), ("U: x\nN: ", 2));
        let last = ChatSettings { history: "last".into(), turns: 1, ..ChatSettings::default() };
        let b = build_prompt(&m, &last, &earlier, &msg("user", "x"), "").unwrap();
        assert_eq!(b.prompt, "U: how are you\nN: well\nU: x\nN: ");
    }

    #[test]
    fn long_history_and_attachments_are_fitted_to_the_context() {
        let m = model(128);
        let s = ChatSettings::default();
        let mut earlier = Vec::new();
        for i in 0..40 {
            earlier.push(msg("user", &format!("question number {i}")));
            earlier.push(msg("model", &format!("answer number {i}")));
        }
        let b = build_prompt(&m, &s, &earlier, &msg("user", "last one"), "").unwrap();
        assert!(b.prompt_tokens + b.reply_limit <= 128);
        assert!(b.turns_used > 0 && b.turns_left_out > 0);
        assert!(b.prompt.contains("answer number 39"), "the newest turns are kept");
        let mut with_file = msg("user", "read this");
        with_file.attachments.push(
            check_attachment(
                &m,
                Attachment {
                    kind: "text".into(),
                    name: "a.txt".into(),
                    text: "word ".repeat(400),
                    data: String::new(),
                    bytes: 2000,
                    dropped: 0,
                    tokens: 0,
                },
            )
            .unwrap(),
        );
        let b = build_prompt(&m, &s, &earlier, &with_file, "").unwrap();
        assert!(b.attachment_tokens_cut > 0);
        assert_eq!(b.turns_used, 0);
        assert!(b.prompt.ends_with("U: read this\nN: "));
        assert!(b.prompt_tokens + b.reply_limit <= 128);
    }

    #[test]
    fn messages_and_files_become_the_models_alphabet() {
        let m = model(256);
        let u = user_message(&m, "  “Héllo” — wörld \u{1F600}\n ", Vec::new()).unwrap();
        assert_eq!(u.text, "\"Hello\" - world");
        assert_eq!(u.dropped, 1);
        assert!(user_message(&m, "\u{1F600}", Vec::new()).is_err());
        let a = attachment_of(&m, "notes.md", "# Title\n\nSome **bold** text.".as_bytes().to_vec()).unwrap();
        assert_eq!(a.kind, "text");
        assert!(!a.text.contains("**"));
        let img = attachment_of(&m, "p.png", vec![0x89, b'P', b'N', b'G']).unwrap();
        assert_eq!(img.data, "data:image/png;base64,iVBORw==");
        assert!(attachment_of(&m, "x.exe", vec![1, 2]).is_err());
        assert_eq!(base64(b"Man"), "TWFu");
        assert_eq!(base64(b"Ma"), "TWE=");
    }
}
